//! Gate 7 / 07 §2.4 on-route alignment cases, replayed from the GPX-like fixtures in
//! core-rust/tests/fixtures/route (generated by gen_route_fixtures.py, which plays the C++
//! route side and Kotlin's one-time rounding). Run with `--nocapture` to see the recorded
//! values (fix counts, segments examined, dc_tick p95 / max per mode).
use contracts::horizon::{HorizonStatus, ManeuverHorizon};
use contracts::route::{RouteBundle, RouteCommitRequest};
use contracts::tick::{PlannerCmd, SearchPriority, TickInput, TickOutput};
use drive_core::{Session, SessionConfig};
use serde_json::Value;
use std::time::{Duration, Instant};

fn fixture(name: &str) -> Value {
    let p = format!(
        "{}/../../tests/fixtures/route/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    serde_json::from_slice(&std::fs::read(&p).unwrap()).unwrap()
}

struct Step {
    input: TickInput,
    out: TickOutput,
    status: Option<HorizonStatus>,
    off_run: u32,
    progress: Option<u32>,
    /// Remaining ETA right after the tick (ms; only while tracking).
    eta_ms: Option<u32>,
    elapsed: Duration,
    grid: bool,
}

struct Run {
    s: Session,
    steps: Vec<Step>,
}

impl Run {
    fn horizons(&self) -> Vec<&ManeuverHorizon> {
        self.steps
            .iter()
            .filter_map(|s| s.out.horizon.as_ref())
            .collect()
    }

    fn reroute_starts(&self) -> Vec<(usize, &PlannerCmd)> {
        self.steps
            .iter()
            .enumerate()
            .flat_map(|(i, s)| s.out.planner_cmds.iter().map(move |c| (i, c)))
            .filter(|(_, c)| {
                matches!(
                    c,
                    PlannerCmd::Start {
                        priority: SearchPriority::Reroute,
                        ..
                    }
                )
            })
            .collect()
    }
}

/// Commits the fixture's bundle as the first route, replays every tick and checks the
/// per-tick `expect` fields (`status`, `off_run`, `low_accuracy_run`, `reroute`,
/// `reacquired`).
fn replay(name: &str) -> Run {
    let fx = fixture(name);
    let mut s = Session::new(SessionConfig::default());
    let bundle: RouteBundle = serde_json::from_value(fx["bundle"].clone()).unwrap();
    s.route_commit(&RouteCommitRequest {
        route_key: None,
        bundle,
    })
    .unwrap_or_else(|e| panic!("{name}: {e:?}"));
    let mut steps = Vec::new();
    for (i, t) in fx["ticks"].as_array().unwrap().iter().enumerate() {
        let input: TickInput = serde_json::from_value(t["input"].clone()).unwrap();
        let grid_before = s.align_stats().grid_fixes;
        let t0 = Instant::now();
        let out = s.tick(input.clone());
        let elapsed = t0.elapsed();
        let now = input.now_mono_ms;
        let st = Step {
            status: s.horizon_status(now),
            off_run: s.aligner().off_run(),
            progress: s.aligner().progress_cm(),
            eta_ms: s.remaining_eta_ms(now),
            grid: s.align_stats().grid_fixes > grid_before,
            input,
            out,
            elapsed,
        };
        let e = &t["expect"];
        let at = format!("{name}: tick {i} (now {now})");
        if let Some(want) = e.get("status") {
            let want: HorizonStatus = serde_json::from_value(want.clone()).unwrap();
            assert_eq!(st.status, Some(want), "{at}");
        }
        if let Some(want) = e.get("off_run") {
            assert_eq!(u64::from(st.off_run), want.as_u64().unwrap(), "{at}");
        }
        if let Some(want) = e.get("low_accuracy_run") {
            assert_eq!(
                u64::from(s.aligner().low_accuracy_run()),
                want.as_u64().unwrap(),
                "{at}"
            );
        }
        if let Some(want) = e.get("reroute") {
            let got = st.out.planner_cmds.iter().any(|c| {
                matches!(
                    c,
                    PlannerCmd::Start {
                        priority: SearchPriority::Reroute,
                        ..
                    }
                )
            });
            assert_eq!(got, want.as_bool().unwrap(), "{at}");
        }
        if let Some(want) = e.get("reacquired") {
            assert_eq!(
                st.grid,
                want.as_bool().unwrap(),
                "{at}: grid re-acquisition"
            );
        }
        // Every emitted horizon is a valid frame: frame_seq strictly increasing, <= 3 entries.
        if let Some(h) = &st.out.horizon {
            assert!(h.upcoming.len() <= 3, "{at}");
            assert_eq!(h.frame_seq, s.frame_seq(), "{at}");
        }
        steps.push(st);
    }
    Run { s, steps }
}

fn percentile(mut v: Vec<Duration>, p: usize) -> Duration {
    if v.is_empty() {
        return Duration::ZERO;
    }
    v.sort();
    v[(v.len() * p / 100).min(v.len() - 1)]
}

/// 07 §2.4: record segments examined and dc_tick p95 / max, normal running vs re-acquisition.
fn record(name: &str, r: &Run) {
    let st = r.s.align_stats();
    let (grid, local): (Vec<&Step>, Vec<&Step>) = r
        .steps
        .iter()
        .filter(|s| s.input.fix.is_some())
        .partition(|s| s.grid);
    let times = |v: &[&Step]| v.iter().map(|s| s.elapsed).collect::<Vec<_>>();
    println!(
        "[gate7] {name}: local fixes={} segs avg={} max={} | grid fixes={} segs avg={} max={} | \
         dc_tick local p95={:?} max={:?} grid p95={:?} max={:?}",
        st.local_fixes,
        st.local_segs.checked_div(st.local_fixes).unwrap_or(0),
        st.local_segs_max,
        st.grid_fixes,
        st.grid_segs.checked_div(st.grid_fixes).unwrap_or(0),
        st.grid_segs_max,
        percentile(times(&local), 95),
        times(&local).into_iter().max().unwrap_or_default(),
        percentile(times(&grid), 95),
        times(&grid).into_iter().max().unwrap_or_default(),
    );
}

/// Case 1: chunk boundaries (and a leg boundary). Progress is continuous: each 1 s fix at
/// 20 m/s advances 18..22 m, never jumps, never goes back; 0 off-route; finished.
#[test]
fn chunk_boundary_progress_is_continuous() {
    let r = replay("gate7-chunk-boundary.json");
    record("chunk-boundary", &r);
    let route = r.s.route().unwrap();
    assert!(route.chunks.len() >= 5, "chunks: {}", route.chunks.len());
    let prog: Vec<u32> = r
        .steps
        .iter()
        .filter(|s| s.input.fix.is_some())
        .filter_map(|s| s.progress)
        .collect();
    assert!(prog.len() > 300);
    // The last fix is 5 m past the end: compare only the regular 20 m steps.
    for w in prog[..prog.len() - 2].windows(2) {
        let d = w[1] - w[0];
        assert!((1_800..=2_200).contains(&d), "step {d} cm at {}", w[0]);
    }
    assert!(r.steps.iter().all(|s| s.off_run == 0));
    assert!(r.reroute_starts().is_empty());
    assert_eq!(
        r.steps.last().unwrap().status,
        Some(HorizonStatus::Finished)
    );
    // The horizon followed the maneuvers: right, left (leg 0), right, arrive (leg 1).
    let first = r.horizons()[1];
    assert_eq!(first.status, HorizonStatus::Tracking);
    assert_eq!(first.upcoming.len(), 3);
    assert!(first.upcoming[0].from_vehicle_m.is_some());
    assert!(first.upcoming[1].seg_from_prev_m.is_some());
    let last = *r.horizons().last().unwrap();
    assert_eq!(last.status, HorizonStatus::Finished);
    assert!(last.upcoming.is_empty());
    // Chunk boundaries are crossed with fixes evaluated in both chunks' planes.
    assert!(
        r.s.align_stats().grid_fixes <= 1,
        "only the first fix uses the grid"
    );
}

/// Added case: a frontage road 20 m away in the same direction is NOT detected (20 m is
/// inside lateral_tol 30 m). Recorded as a known limit.
#[test]
fn side_road_20m_is_not_detected() {
    let r = replay("gate7-side-road-20m.json");
    record("side-road-20m", &r);
    let on_side = r
        .steps
        .iter()
        .filter(|s| {
            s.input
                .fix
                .is_some_and(|f| f.lat_e7 > r.steps[1].input.fix.unwrap().lat_e7 + 1_000)
        })
        .count();
    println!("[gate7] side-road-20m: {on_side} fixes on the side road, off-route detections 0 (not detected: 20 m < 30 m)");
    assert!(on_side > 90);
    assert!(r.reroute_starts().is_empty());
}

/// Added case: exactly 30.00 m (3000 cm) is on the route, 30.01 m (3001 cm) is off; three
/// in a row confirm and start the reroute with the third fix.
#[test]
fn lateral_30m_boundary() {
    let r = replay("gate7-lateral-30m-boundary.json");
    let starts = r.reroute_starts();
    assert_eq!(starts.len(), 1);
    let (i, PlannerCmd::Start { fix: Some(f), .. }) = starts[0] else {
        panic!("{starts:?}")
    };
    assert_eq!(i, r.steps.len() - 1);
    assert_eq!(
        Some(*f),
        r.steps[i].input.fix,
        "the confirming fix is the new origin"
    );
    // off_route / rerouting: old guidance withheld
    let h = r.steps[i].out.horizon.as_ref().unwrap();
    assert_eq!(h.status, HorizonStatus::Rerouting);
    assert!(h.upcoming.is_empty());
    assert!(r.steps[i].out.ui_cmds.is_empty(), "no show_checking_route");
    assert_eq!(
        r.steps[i].eta_ms, None,
        "off-route invalidates the remaining ETA"
    );
    assert!(r.steps[1].eta_ms.is_some());
}

/// Added case: a side road branching off and reaching 40 m. Records the number of fixes
/// from the branch point until off-route is confirmed.
#[test]
fn branch_to_40m_detected_after_n_fixes() {
    let r = replay("gate7-branch-40m.json");
    let starts = r.reroute_starts();
    assert_eq!(starts.len(), 1, "one reroute, never repeated while it runs");
    let detect = starts[0].0;
    // first fix past the branch point (x 1000 m = 15 m/s * 66.7 s → first fix at t >= 67.7 s)
    let branch = r
        .steps
        .iter()
        .position(|s| s.input.fix.is_some_and(|f| f.at_mono_ms >= 1_000 + 66_667))
        .unwrap();
    let first_off = r.steps.iter().position(|s| s.off_run == 1).unwrap();
    println!(
        "[gate7] branch-40m: branch at tick {branch}, first fix beyond 30 m at tick {first_off}, \
         off-route confirmed at tick {detect}: {} fixes after the branch ({} s at 15 m/s)",
        detect - branch + 1,
        detect - branch + 1
    );
    assert_eq!(detect - first_off, 2, "confirm_fixes = 3");
    assert!(
        detect - branch < 16,
        "detected within 16 fixes of the branch"
    );
    assert_eq!(r.steps[detect].status, Some(HorizonStatus::Rerouting));
}

/// Added case: position jitter on the main line (+-25 m, +-20 deg, occasional 45 m
/// accuracy): 0 false detections.
#[test]
fn jitter_on_main_line_never_detects_off_route() {
    let r = replay("gate7-jitter-main.json");
    record("jitter-main", &r);
    assert!(r.reroute_starts().is_empty());
    let max_run = r.steps.iter().map(|s| s.off_run).max().unwrap();
    println!("[gate7] jitter-main: max off-route run {max_run}, false detections 0");
    assert!(r.steps.iter().all(|s| !matches!(
        s.status,
        Some(HorizonStatus::OffRoute | HorizonStatus::Rerouting)
    )));
}

/// Added case: off x2 → low accuracy x2 → off x1: the run ends at 1, no reroute.
#[test]
fn low_accuracy_fix_resets_the_off_route_run() {
    let r = replay("gate7-off-run-reset.json");
    assert_eq!(r.steps.last().unwrap().off_run, 1);
    assert!(r.reroute_starts().is_empty());
}

/// Case 7: valid off-route and low-accuracy fixes alternate: off-route is never confirmed
/// (known trade-off of the reset rule); the status turns uncertain. Records elapsed time
/// and fix count.
#[test]
fn alternating_off_and_low_accuracy_never_confirms() {
    let r = replay("gate7-off-lowacc-alternating.json");
    assert!(r.reroute_starts().is_empty());
    assert!(r.steps.iter().all(|s| s.off_run <= 1));
    let fixes = r.steps.iter().filter(|s| s.input.fix.is_some()).count() - 1;
    let first = r.steps[2].input.now_mono_ms;
    let last = r.steps.last().unwrap().input.now_mono_ms;
    println!(
        "[gate7] off-lowacc-alternating: {fixes} fixes over {} ms without confirming off-route \
         (reset rule trade-off); final status {:?}",
        last - first,
        r.steps.last().unwrap().status
    );
    assert_eq!(
        r.steps.last().unwrap().status,
        Some(HorizonStatus::Uncertain)
    );
}

/// Case 2: parallel carriageways of the same route 20 m apart. Standing still between
/// them (bearing unusable below 1.4 m/s): ambiguous → uncertain; moving east → tracking.
#[test]
fn parallel_road_ambiguous_until_heading_decides() {
    let r = replay("gate7-parallel-ambiguous.json");
    // right after the commit: uncertain (no fix yet), first frame
    let h = r.steps[0].out.horizon.as_ref().unwrap();
    assert_eq!(h.status, HorizonStatus::Uncertain);
    assert_eq!(h.matched_progress_cm, None);
    // ambiguous fixes keep it uncertain: no progress / ETA, and since nothing changed, no
    // new frame
    for st in &r.steps[1..3] {
        assert_eq!(st.status, Some(HorizonStatus::Uncertain));
        assert_eq!(st.progress, None);
        assert_eq!(st.eta_ms, None);
        assert!(st.out.horizon.is_none());
        assert!(st.out.log.iter().any(|l| l.what == "align_ambiguous"));
    }
    let h = r.steps[3].out.horizon.as_ref().unwrap();
    assert_eq!(h.status, HorizonStatus::Tracking);
    let p = h.matched_progress_cm.unwrap();
    assert!((100_000..=102_000).contains(&p), "eastbound part: {p}");
    assert!(r.reroute_starts().is_empty());
}

/// Case 3: tunnel. Fixes stop; 2.5 s later the status becomes uncertain without new input
/// (next_wake); the first fix after the exit is re-acquired through the grid.
#[test]
fn tunnel_recovery_reacquires_through_the_grid() {
    let r = replay("gate7-tunnel-recovery.json");
    record("tunnel-recovery", &r);
    let last_fix = r
        .steps
        .iter()
        .rposition(|s| {
            s.input.fix.is_some()
                && s.status == Some(HorizonStatus::Tracking)
                && !s.grid
                && s.input.now_mono_ms < 100_000
        })
        .unwrap();
    let stale_at = r.steps[last_fix].input.fix.unwrap().at_mono_ms + 2_501;
    assert_eq!(r.steps[last_fix].out.next_wake_mono_ms, Some(stale_at));
    let stale = r
        .steps
        .iter()
        .find(|s| s.input.now_mono_ms == stale_at)
        .unwrap();
    let h = stale
        .out
        .horizon
        .as_ref()
        .expect("status change is a new frame");
    assert_eq!(h.status, HorizonStatus::Uncertain);
    // distances frozen while uncertain (same upcoming as the last tracking frame)
    let before = r.steps[..=last_fix]
        .iter()
        .rev()
        .find_map(|s| s.out.horizon.as_ref())
        .unwrap();
    let mut frozen = before.upcoming.clone();
    for entry in &mut frozen {
        entry.eta_range_ms = None;
    }
    assert_eq!(h.upcoming, frozen);
    // no frames while nothing changes in the tunnel
    let quiet = r
        .steps
        .iter()
        .filter(|s| s.input.fix.is_none() && s.input.now_mono_ms > stale_at)
        .all(|s| s.out.horizon.is_none());
    assert!(quiet);
    // exit: grid re-acquisition, progress ~4520 m, the 2.5 km maneuver is passed
    let exit = r
        .steps
        .iter()
        .position(|s| s.grid && s.input.fix.is_some() && s.input.now_mono_ms > 100_000)
        .unwrap();
    let h = r.steps[exit].out.horizon.as_ref().unwrap();
    assert_eq!(h.status, HorizonStatus::Tracking);
    let p = h.matched_progress_cm.unwrap();
    assert!((450_000..=454_000).contains(&p), "{p}");
    assert!(h.upcoming[0].maneuver.anchor.along_route_cm < p);
    let h = r.steps[exit + 1].out.horizon.as_ref().unwrap();
    assert!(h
        .upcoming
        .iter()
        .all(|e| e.maneuver.anchor.along_route_cm > p));
    // next maneuver: the one at 5 km (plane-rounded along, within 1 m)
    let next = h.upcoming[0].maneuver.anchor.along_route_cm;
    assert!(next.abs_diff(500_000) <= 100, "{next}");
    assert!(r.reroute_starts().is_empty());
}

/// Replays are deterministic: same bytes every time.
#[test]
fn alignment_replay_is_byte_identical() {
    for name in ["gate7-chunk-boundary.json", "gate7-jitter-main.json"] {
        let a: Vec<Vec<u8>> = replay(name)
            .steps
            .iter()
            .map(|s| serde_json::to_vec(&s.out).unwrap())
            .collect();
        let b: Vec<Vec<u8>> = replay(name)
            .steps
            .iter()
            .map(|s| serde_json::to_vec(&s.out).unwrap())
            .collect();
        assert_eq!(a, b, "{name}");
    }
}
